/**
 * senaite.starter: CNIC auto-fill
 *
 * When a patient is selected in the "Medical Record #" field of a sample,
 * senaite.patient fills the patient fields of the sample with the values of
 * that patient and clears them when the patient is deselected
 * (senaite.patient: webpack/app/components/temporaryidentifierwidget.coffee).
 *
 * This does the same for the CNIC field, using the same widget events and the
 * same JSON endpoint.
 */
(function () {
  "use strict";

  // MRN placeholder of senaite.patient for temporary (autogenerated) MRNs
  var AUTO_WILDCARD = "-- autogenerated --";
  var FIELD_NAME = "CNIC";
  var PATIENT_CATALOG = "senaite_catalog_patient";

  function is_add_sample_form() {
    return document.body.classList.contains("template-ar_add");
  }

  function get_portal_url() {
    var input = document.querySelector("input[name='portal_url']");
    return (input && input.value) || window.portal_url || "";
  }

  // The MRN widget the event was fired from, if any
  function get_mrn_widget(event) {
    var target = event.target;
    if (!target || !target.closest) {
      return null;
    }
    return target.closest(".TemporaryIdentifier");
  }

  // The CNIC input of the same sample (column of the add form) as the widget
  function get_cnic_input(widget) {
    var name = FIELD_NAME;
    if (is_add_sample_form()) {
      var column = widget.closest("td[arnum]");
      if (!column) {
        return null;
      }
      name = FIELD_NAME + "-" + column.getAttribute("arnum");
    }
    return document.querySelector("[name='" + name + "']");
  }

  // Set the value with the native setter, so ReactJS components notice it
  function set_value(input, value) {
    var proto = window.HTMLInputElement.prototype;
    if (input.tagName === "TEXTAREA") {
      proto = window.HTMLTextAreaElement.prototype;
    }
    Object.getOwnPropertyDescriptor(proto, "value").set.call(input, value);
    input.dispatchEvent(new Event("input", {bubbles: true}));
  }

  // Resolves with the CNIC of the patient with the given MRN or null if there
  // is no patient with that MRN
  function fetch_patient_cnic(mrn) {
    var catalog = document.querySelector("[name='config_catalog']");
    var params = new URLSearchParams();
    params.append("portal_type", "Patient");
    params.append("catalog_name", (catalog && catalog.value) || PATIENT_CATALOG);
    params.append("patient_mrn", mrn);
    params.append("include_fields", "mrn,cnic");
    params.append("page_size", "1");

    return fetch(get_portal_url() + "/@@API/read", {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"
      },
      body: params.toString()
    }).then(function (response) {
      return response.ok ? response.json() : {};
    }).then(function (data) {
      var objects = (data && data.objects) || [];
      if (!objects.length) {
        return null;
      }
      return objects[0].cnic || "";
    });
  }

  function on_mrn_selected(event) {
    var widget = get_mrn_widget(event);
    // "select" is also fired by browsers when text is selected in an input,
    // but only the events of the widget carry the selected value
    var detail = event.detail;
    if (!widget || !detail || typeof detail !== "object") {
      return;
    }
    var mrn = detail.value;
    if (!mrn || mrn === AUTO_WILDCARD) {
      return;
    }
    fetch_patient_cnic(mrn).then(function (cnic) {
      // keep the value entered by the user for new patients
      if (cnic === null) {
        return;
      }
      var input = get_cnic_input(widget);
      if (input) {
        set_value(input, cnic);
      }
    }).catch(function (error) {
      console.error("[senaite.starter.cnic]", error);
    });
  }

  function on_mrn_deselected(event) {
    var widget = get_mrn_widget(event);
    if (!widget) {
      return;
    }
    var input = get_cnic_input(widget);
    if (input) {
      set_value(input, "");
    }
  }

  function init() {
    // custom events fired by the QuerySelect widget of the MRN field
    document.body.addEventListener("select", on_mrn_selected);
    document.body.addEventListener("deselect", on_mrn_deselected);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
}());
